scwin.onpageunload = function() {};
scwin.grd_onviewchange = function(info) {
    console.log(info);
    if (info.colIndex === 0) { //  첫번째 컬럼 
        var inputType = info.newValue;
        //debugger;
        var obj = scwin.inputTypeCustomObj[inputType];
        if (info.newValue == "calendar") {
            var calendarValueType = dataList1.getCellData(info.rowIndex, "col3")
            obj.options.calendarValueType = calendarValueType;
            var data = calendarValueType == "yearMonthDate" ? "20210108" : "202101081131";
            dataList1.setCellData(info.rowIndex, "col2", data)
        }
        console.log(obj);
        grd.setCellInputType(info.rowIndex, "col2", obj);
        if (info.newValue == "input") {
            grd.setCellDisplayFormat(info.rowIndex, "col2", "######-#######");
            console.log("setcelldisplayformats")
        }
        //grd.setCellClass( info.rowIndex , "col2" , "test2" );
    } else if (info.colIndex === 1) { // 두번째 컬럼
        var newV = info.newValue;
        console.log("newV is ", newV);
        if (newV === "3") {
            var obj = scwin.inputTypeCustomObj["autoComplete"];
            grd.setCellInputType(info.rowIndex, "col2", obj);
            dataList1.setCellData(info.rowIndex, "col2", newV)
        } else {
            var obj = scwin.inputTypeCustomObj["select"];
            grd.setCellInputType(info.rowIndex, "col2", obj);
            dataList1.setCellData(info.rowIndex, "col2", newV)
        }
    }
};
scwin.grd_onbeforeedit = function(row, col, value) {
    if (col == 1) {
        console.log("onbeforeedit: ", row, col, value);
        //grd.setCellDisplayFormat( row, "col2", "######-#######");
    }
};
scwin.grd_oncellindexchange = function(row, col, oldRow, oldCol) {
    // 해당 컬럼에 nodeset 에 맞는 데이터를 동적으로 조회
    var sel_sampleData = [{
            "codeLB": "축구",
            "codeVL": "1"
        },
        {
            "codeLB": "농구",
            "codeVL": "2"
        },
        {
