            "codeLB": "배구",
            "codeVL": "4"
        }
    ];
    sel_sample2.setJSON(sel_sampleData);
    var sel_sampleData2 = [{
            "codeLB": "피자",
            "codeVL": "1"
        },
        {
            "codeLB": "치킨",
            "codeVL": "2"
