        }
    ];
    sel_sample3.setJSON(sel_sampleData2);
    var sel_sampleData3 = [{
            "codeLB": "모니터",
            "codeVL": "1"
        },
        {
            "codeLB": "키보드",
            "codeVL": "2"
        },
        {
            "codeLB": "마우스",
            "codeVL": "3"
        },
        {
            "codeLB": "노트북",
            "codeVL": "4"
        }
    ];
    sel_sample.setJSON(sel_sampleData3);
    console.log("oncellindexchange", row, col, oldRow, oldCol);
    if (col == 1) {
        var obj = {
            inputType: "autoComplete",
            itemTableType: "gridViewItemset",
            options: {
                viewType: "icon",
                displayMode: "label",
                noResult: "useData",
                selectedData: "false",
                search: "contain",
                searchtarget: "label",
                chooseOptionLabel: "-- 선택 --",
                chooseOptionValue: "",
            },
            visibleRowNum: 10,
            width: 330,
            hideHeader: true,
            nodeset: row % 3 === 0 ? "data:sel_sample" : row % 2 === 0 ? "data:sel_sample2" : "data:sel_sample3",
            label: "codeLB",
            value: "codeVL",
            item: [{
                    ref: "codeLB",
                    header: "label"
                },
                {
                    ref: "codeVL",
                    header: "value"
                },
            ],
        };
        console.log(obj);
        grd.setCellInputType(row, col, obj);
    }
};
