scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grd_cell_1_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grd_cell_2_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.logger.getErrorLog() == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.inputTypeCustomObj = {
        calendar: {
            inputType: "calendar",
            options: {
                calendarValueType: "yearMonthDate"
            }
        },
        radio: {
            inputType: "radio"
        },
        checkbox: {
            inputType: "checkbox"
        },
        input: {
            inputType: "text"
        },
        select: {
            inputType: "select",
            options: {
                viewType: "icon"
            },
            itemSet: {
                nodeset: "data:sel_sample",
                label: "codeLB",
                value: "codeVL"
            }
        },
        autoComplete: {
            inputType: "autoComplete",
            options: {
                viewType: "icon"
            },
            itemSet: {
                nodeset: "data:sel_sample",
                label: "codeLB",
                value: "codeVL"
            }
        },
        button: {
            inputType: "button"
        },
        link: {
            inputType: "link"
        }
    };
    //값 변경 시 col2의 inputType을 동적으로 변경한다.
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
